/**
 * V27 — ContactReferralsTab: full-screen Referenze tab content.
 * - Big "Chiedi Referenze" WhatsApp button (uses Master-configured template)
 * - "Aggiungi referenza" button that starts a chain (returns here after each save)
 * - Scrollable list of all referrals generated by this contact
 */
import { useCallback, useState } from "react";
import { View, Text, StyleSheet, Pressable, ScrollView, ActivityIndicator, Platform, Linking, TextInput, Modal } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import { useRouter, useFocusEffect } from "expo-router";
import { api } from "@/src/api";
import { notify } from "@/src/utils/notify";
import { useSafeBottom } from "@/src/hooks/useSafeBottom";

import { useBottomSheetPadding } from "@/src/utils/bottomSheetInsets";
import { HT } from "@/src/homeTheme"; // V50.z335 — Contatti dark/premium
type Referral = {
  contact_id: string;
  first_name?: string;
  last_name?: string;
  phone?: string;
  email?: string;
  status?: string;
  contact_code?: string;
  area?: string;
  referral_note?: string;
};

type Props = {
  contactId: string;
  contactName: string;
  contactPhone?: string;
};

const C = { primary: "#FF6B35", primarySoft: "#FFF1E9", navy: HT.text, muted: HT.muted, wa: "#25D366" };

export function ContactReferralsTab({ contactId, contactName, contactPhone }: Props) {
  const router = useRouter();
  const safeBottom = useSafeBottom(); // V29.aq
  const [items, setItems] = useState<Referral[]>([]);
  const bottomPad = useBottomSheetPadding();
  const [loading, setLoading] = useState(true);
  const [waTemplate, setWaTemplate] = useState<string>("");
  const [showWaModal, setShowWaModal] = useState(false);
  const [waMessage, setWaMessage] = useState<string>("");

  const load = useCallback(async () => {
    try {
      setLoading(true);
      const [r, s] = await Promise.all([
        api<{ referred_by: Referral | null; referrals: Referral[] }>(`/contacts/${contactId}/referrals`).catch(() => ({ referred_by: null, referrals: [] })),
        api<{ wa_referral_template?: string }>(`/settings`).catch(() => ({ wa_referral_template: "" })),
      ]);
      setItems(Array.isArray(r?.referrals) ? r.referrals : []);
      setWaTemplate(s.wa_referral_template || "");
    } catch (e: any) {
      console.warn("referrals-tab load", e?.message);
    } finally { setLoading(false); }
  }, [contactId]);

  useFocusEffect(useCallback(() => { load(); }, [load]));

  const addReferral = () => {
    router.push(`/contact/new?source=referral&referred_by=${contactId}&chain=1&back_to=${contactId}` as any);
  };

  const openWa = () => {
    const msg = (waTemplate || "").replace(/\{name\}/g, contactName || "");
    setWaMessage(msg);
    setShowWaModal(true);
  };

  const sendWa = () => {
    const encoded = encodeURIComponent(waMessage || "");
    // Prefer contact's phone if available; else open WhatsApp chooser
    const clean = (contactPhone || "").replace(/[^\d+]/g, "");
    const url = clean ? `https://wa.me/${clean.replace(/^\+/, "")}?text=${encoded}` : `https://wa.me/?text=${encoded}`;
    setShowWaModal(false);
    if (Platform.OS === "web") {
      try { window.open(url, "_blank"); } catch { /* ignore */ }
    } else {
      Linking.openURL(url).catch(() => notify("Errore", "Impossibile aprire WhatsApp"));
    }
  };

  return (
    <ScrollView contentContainerStyle={{ padding: 16, paddingBottom: 180 }}>
      <Text style={styles.title}>Referenze di {contactName}</Text>
      <Text style={styles.sub}>
        {items.length === 0 ? "Nessuna referenza ancora generata" : `${items.length} referenza/e generate`}
      </Text>

      {/* Actions */}
      <View style={styles.actionsRow}>
        <Pressable testID="refs-add-btn" onPress={addReferral} style={[styles.btn, { backgroundColor: C.primary, flex: 1 }]}>
          <Ionicons name="person-add" size={18} color="#FFF" />
          <Text style={styles.btnTxt}>Aggiungi referenza</Text>
        </Pressable>
        <Pressable testID="refs-wa-btn" onPress={openWa} style={[styles.btn, { backgroundColor: C.wa, flex: 1 }]}>
          <Ionicons name="logo-whatsapp" size={20} color="#FFF" />
          <Text style={styles.btnTxt}>Chiedi Referenze</Text>
        </Pressable>
      </View>

      {/* List */}
      {loading ? (
        <ActivityIndicator style={{ marginTop: 30 }} color={C.primary} />
      ) : items.length === 0 ? (
        <View style={styles.empty}>
          <Ionicons name="share-social-outline" size={38} color={C.muted} />
          <Text style={styles.emptyTxt}>Nessuna referenza da questo cliente</Text>
          <Text style={styles.emptySub}>Tocca &quot;Aggiungi referenza&quot; per iniziare a inserire i contatti che ti ha passato</Text>
        </View>
      ) : (
        <View style={{ marginTop: 14, gap: 8 }}>
          {items.map((r) => {
            const fullName = `${r.first_name || ""} ${r.last_name || ""}`.trim() || "(senza nome)";
            return (
              <Pressable
                key={r.contact_id}
                testID={`ref-item-${r.contact_id}`}
                onPress={() => router.push(`/contact/${r.contact_id}` as any)}
                style={styles.row}
              >
                <View style={styles.avatar}>
                  <Text style={styles.avatarTxt}>
                    {(r.first_name?.[0] || "").toUpperCase()}{(r.last_name?.[0] || "").toUpperCase()}
                  </Text>
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={styles.rowName} numberOfLines={1}>{fullName}</Text>
                  <Text style={styles.rowSub} numberOfLines={1}>{r.phone || r.email || r.contact_code || "—"}</Text>
                  {r.referral_note ? <Text style={styles.rowNote} numberOfLines={2}>💬 {r.referral_note}</Text> : null}
                </View>
                {r.status && (
                  <View style={[styles.statusMini, { backgroundColor: (r.status === "collaborator" ? "#7C3AED" : r.status === "client" ? "#16A34A" : "#0891B2") + "22" }]}>
                    <Text style={[styles.statusMiniTxt, { color: r.status === "collaborator" ? "#7C3AED" : r.status === "client" ? "#16A34A" : "#0891B2" }]}>
                      {r.status === "collaborator" ? "Collab." : r.status === "client" ? "Cliente" : "Prospect"}
                    </Text>
                  </View>
                )}
                <Ionicons name="chevron-forward" size={18} color={C.muted} />
              </Pressable>
            );
          })}
        </View>
      )}

      {/* WhatsApp preview modal */}
      <Modal visible={showWaModal} transparent animationType="slide" onRequestClose={() => setShowWaModal(false)}>
        <View style={styles.back}>
          <View style={[styles.sheet, { paddingBottom: safeBottom + 12 }, { paddingBottom: bottomPad }]}>
            <View style={styles.sheetHdr}>
              <Text style={styles.sheetTitle}>Messaggio da inviare</Text>
              <Pressable onPress={() => setShowWaModal(false)} hitSlop={10}><Ionicons name="close" size={22} color={C.navy} /></Pressable>
            </View>
            <Text style={styles.helpTxt}>
              Anteprima del testo configurato dal Master (le impostazioni). Il cliente lo inoltrerà ai propri contatti dal suo WhatsApp — puoi modificarlo prima di aprire l&apos;app.
            </Text>
            <TextInput
              testID="wa-preview-input"
              value={waMessage}
              onChangeText={setWaMessage}
              multiline
              placeholder="Scrivi il messaggio…"
              placeholderTextColor={HT.muted}
              style={styles.textarea}
            />
            <Pressable testID="wa-send-btn" onPress={sendWa} style={[styles.btn, { backgroundColor: C.wa, marginTop: 12 }]}>
              <Ionicons name="logo-whatsapp" size={22} color="#FFF" />
              <Text style={styles.btnTxt}>Invia su WhatsApp</Text>
            </Pressable>
          </View>
        </View>
      </Modal>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  title: { fontSize: 18, fontWeight: "800", color: C.navy, letterSpacing: -0.3 },
  sub: { fontSize: 12, color: C.muted, marginTop: 4, fontWeight: "600", marginBottom: 12 },
  actionsRow: { flexDirection: "row", gap: 10, marginBottom: 8 },
  btn: { flexDirection: "row", alignItems: "center", justifyContent: "center", gap: 8, borderRadius: 14, paddingHorizontal: 12, paddingVertical: 13 },
  btnTxt: { color: "#FFF", fontWeight: "800", fontSize: 13 },
  empty: { alignItems: "center", padding: 30, gap: 8, marginTop: 16, backgroundColor: HT.card, borderRadius: 14, borderWidth: 1, borderColor: HT.border, borderStyle: "dashed" },
  emptyTxt: { color: C.navy, fontWeight: "800", fontSize: 14 },
  emptySub: { color: C.muted, fontSize: 12, textAlign: "center" },
  row: { flexDirection: "row", alignItems: "center", gap: 10, backgroundColor: HT.card, borderRadius: 12, padding: 12, borderWidth: 1, borderColor: HT.border },
  avatar: { width: 42, height: 42, borderRadius: 21, backgroundColor: C.primarySoft, alignItems: "center", justifyContent: "center" },
  avatarTxt: { color: C.primary, fontWeight: "900", fontSize: 13 },
  rowName: { fontSize: 14, fontWeight: "800", color: C.navy },
  rowSub: { fontSize: 11, color: C.muted, marginTop: 2 },
  rowNote: { fontSize: 11, color: HT.text2, marginTop: 3, fontStyle: "italic" },
  statusMini: { paddingHorizontal: 8, paddingVertical: 3, borderRadius: 999 },
  statusMiniTxt: { fontSize: 10, fontWeight: "800" },
  back: { flex: 1, backgroundColor: "rgba(0,0,0,0.5)", justifyContent: "flex-end" },
  sheet: { backgroundColor: HT.card, borderTopLeftRadius: 22, borderTopRightRadius: 22, padding: 16, paddingBottom: 30 },
  sheetHdr: { flexDirection: "row", justifyContent: "space-between", alignItems: "center", marginBottom: 10 },
  sheetTitle: { fontSize: 17, fontWeight: "800", color: C.navy },
  helpTxt: { fontSize: 12, color: C.muted, marginBottom: 10, lineHeight: 17 },
  textarea: { backgroundColor: HT.card2, borderRadius: 12, padding: 12, minHeight: 160, fontSize: 14, color: C.navy, textAlignVertical: "top" },
});
